CREATE TABLE credentials(id TEXT PRIMARY KEY CHECK(length(id)=32),digest BLOB NOT NULL UNIQUE CHECK(length(digest)=32),account TEXT NOT NULL REFERENCES accounts(account),label TEXT NOT NULL CHECK(length(label) BETWEEN 1 AND 128),principal TEXT NOT NULL CHECK(length(principal) BETWEEN 1 AND 256),revision INTEGER NOT NULL CHECK(revision>=1),all_chats INTEGER NOT NULL CHECK(all_chats IN(0,1)),from_time INTEGER NOT NULL DEFAULT 0,until_time INTEGER NOT NULL DEFAULT 0,rolling INTEGER NOT NULL DEFAULT 0 CHECK(rolling>=0),created_at INTEGER NOT NULL,expires_at INTEGER NOT NULL DEFAULT 0,revoked INTEGER NOT NULL DEFAULT 0 CHECK(revoked IN(0,1)));
CREATE TABLE credential_chats(credential_id TEXT NOT NULL REFERENCES credentials(id) ON DELETE CASCADE,chat_id TEXT NOT NULL REFERENCES chats(id),PRIMARY KEY(credential_id,chat_id));
CREATE INDEX credentials_account_principal ON credentials(account,principal);
